CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),google_subject varchar(255) UNIQUE NOT NULL,email varchar(320) NOT NULL,display_name varchar(200) NOT NULL,photo_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,refresh_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),name varchar(200) NOT NULL,address text NOT NULL,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS room_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id) ON DELETE RESTRICT,name varchar(200) NOT NULL,capacity smallint NOT NULL CHECK(capacity>=1),daily_rate numeric(14,2) NOT NULL DEFAULT 0,weekly_rate numeric(14,2) NOT NULL DEFAULT 0,monthly_rate numeric(14,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS room_type_prices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_type_id uuid NOT NULL REFERENCES room_types(id) ON DELETE RESTRICT,occupancy smallint NOT NULL CHECK(occupancy>=1),billing_period varchar(20) NOT NULL CHECK(billing_period IN('daily','weekly','monthly')),amount numeric(14,2) NOT NULL CHECK(amount>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(room_type_id,occupancy,billing_period));
CREATE TABLE IF NOT EXISTS rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id) ON DELETE RESTRICT,name varchar(100) NOT NULL,monthly_rent numeric(14,2) NOT NULL CHECK(monthly_rent>=0),status varchar(20) NOT NULL DEFAULT 'vacant' CHECK(status IN('vacant','occupied','maintenance')),notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(property_id,name));
CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),room_id uuid NOT NULL REFERENCES rooms(id),full_name varchar(200) NOT NULL,phone varchar(50) NOT NULL,email varchar(320),identity_number varchar(100),move_in_date date NOT NULL,move_out_date date,monthly_rent numeric(14,2) NOT NULL CHECK(monthly_rent>=0),due_day smallint NOT NULL CHECK(due_day BETWEEN 1 AND 31),status varchar(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','moved_out')),notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_tenant_room ON tenants(room_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),tenant_id uuid NOT NULL REFERENCES tenants(id),room_id uuid NOT NULL REFERENCES rooms(id),period_month date NOT NULL,amount numeric(14,2) NOT NULL CHECK(amount>=0),paid_at timestamptz NOT NULL,method varchar(20) NOT NULL CHECK(method IN('cash','transfer','other')),status varchar(20) NOT NULL DEFAULT 'paid' CHECK(status IN('pending','partial','paid','late','cancelled')),reference_number varchar(200),notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS properties_owner_idx ON properties(owner_id); CREATE INDEX IF NOT EXISTS tenants_owner_idx ON tenants(owner_id); CREATE INDEX IF NOT EXISTS payments_owner_idx ON payments(owner_id); CREATE INDEX IF NOT EXISTS payments_period_idx ON payments(period_month);
